if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
// The qbank_usage columns use (SELECT ...) UNION (SELECT ...), which SQLite
// rejects, so the Usage column shows 'Error reading from database'.
\core\plugininfo\qbank::enable_plugin('usage', 0);
echo "Disabled qbank_usage.\n";

if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/lib/questionlib.php');
require_once($CFG->dirroot . '/question/format/xml/format.php');
try {
    global $DB, $USER;
    $USER = get_admin();

    $course = $DB->get_record('course', ['shortname' => 'BULKTAGS01']);
    if (!$course) {
        throw new \RuntimeException("Course 'BULKTAGS01' was not found.");
    }

    $questionbanks = $DB->get_records('qbank', ['course' => $course->id]);
    if (count($questionbanks) !== 1) {
        throw new \RuntimeException("Expected one question bank for course 'BULKTAGS01'; found " . count($questionbanks) . '.');
    }
    $questionbank = reset($questionbanks);
    $questionbankcm = get_coursemodule_from_instance('qbank', $questionbank->id, $course->id);
    if (!$questionbankcm) {
        throw new \RuntimeException("The course-module record for the 'BULKTAGS01' question bank was not found.");
    }
    if ((int) $questionbankcm->id !== 1) {
        throw new \RuntimeException("The question bank must have course-module ID 1 for the configured landing page; found {$questionbankcm->id}.");
    }
    $questionbankcontext = context_module::instance($questionbankcm->id);
    $category = question_get_default_category($questionbankcontext->id, true);
    if (!$category) {
        throw new \RuntimeException("The default question category for course 'BULKTAGS01' was not found or created.");
    }

    // Skip the import if the demo questions are already present.
    $existing = $DB->count_records_sql(
        "SELECT COUNT(1)
           FROM {question} q
           JOIN {question_versions} qv ON qv.questionid = q.id
           JOIN {question_bank_entries} qbe ON qbe.id = qv.questionbankentryid
          WHERE qbe.questioncategoryid = :categoryid
            AND " . $DB->sql_like('q.name', ':name'),
        ['categoryid' => $category->id, 'name' => 'bulktags-%']
    );
    if ($existing > 0) {
        throw new \RuntimeException('Demo questions already present, skipping import.');
    }

    $xml = <<<'BULKTAGSXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="truefalse">
    <name><text>bulktags-001 Capital of France</text></name>
    <questiontext format="html"><text><![CDATA[<p>Paris is the capital of France.</p>]]></text></questiontext>
    <defaultgrade>1</defaultgrade>
    <answer fraction="100" format="moodle_auto_format"><text>true</text><feedback format="html"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>false</text><feedback format="html"><text></text></feedback></answer>
    <tags><tag><text>geography</text></tag><tag><text>easy</text></tag></tags>
  </question>
  <question type="truefalse">
    <name><text>bulktags-002 Longest river</text></name>
    <questiontext format="html"><text><![CDATA[<p>The Thames is the longest river in the world.</p>]]></text></questiontext>
    <defaultgrade>1</defaultgrade>
    <answer fraction="0" format="moodle_auto_format"><text>true</text><feedback format="html"><text></text></feedback></answer>
    <answer fraction="100" format="moodle_auto_format"><text>false</text><feedback format="html"><text></text></feedback></answer>
    <tags><tag><text>geography</text></tag></tags>
  </question>
  <question type="shortanswer">
    <name><text>bulktags-003 Chemical symbol for gold</text></name>
    <questiontext format="html"><text><![CDATA[<p>What is the chemical symbol for gold?</p>]]></text></questiontext>
    <defaultgrade>1</defaultgrade>
    <usecase>0</usecase>
    <answer fraction="100" format="moodle_auto_format"><text>Au</text><feedback format="html"><text></text></feedback></answer>
    <tags><tag><text>science</text></tag><tag><text>hard</text></tag></tags>
  </question>
  <question type="shortanswer">
    <name><text>bulktags-004 Planet nearest the sun</text></name>
    <questiontext format="html"><text><![CDATA[<p>Which planet is nearest the sun?</p>]]></text></questiontext>
    <defaultgrade>1</defaultgrade>
    <usecase>0</usecase>
    <answer fraction="100" format="moodle_auto_format"><text>Mercury</text><feedback format="html"><text></text></feedback></answer>
    <tags><tag><text>science</text></tag></tags>
  </question>
  <question type="truefalse">
    <name><text>bulktags-005 Water boils at 100C</text></name>
    <questiontext format="html"><text><![CDATA[<p>At sea level, water boils at 100&deg;C.</p>]]></text></questiontext>
    <defaultgrade>1</defaultgrade>
    <answer fraction="100" format="moodle_auto_format"><text>true</text><feedback format="html"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>false</text><feedback format="html"><text></text></feedback></answer>
  </question>
  <question type="truefalse">
    <name><text>bulktags-006 Shakespeare wrote Hamlet</text></name>
    <questiontext format="html"><text><![CDATA[<p>William Shakespeare wrote Hamlet.</p>]]></text></questiontext>
    <defaultgrade>1</defaultgrade>
    <answer fraction="100" format="moodle_auto_format"><text>true</text><feedback format="html"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>false</text><feedback format="html"><text></text></feedback></answer>
  </question>
</quiz>
BULKTAGSXML;

    $tmpdir = make_request_directory();
    $tmpfile = $tmpdir . '/bulktags.xml';
    if (file_put_contents($tmpfile, $xml) === false) {
        throw new \RuntimeException('Could not write the temporary question import file.');
    }
    $qformat = new qformat_xml();
    $qformat->setCategory($category);
    $qformat->setContexts([$questionbankcontext]);
    $qformat->setCourse($course);
    $qformat->setFilename($tmpfile);
    $qformat->setMatchgrades('error');
    $qformat->setCatfromfile(false);
    $qformat->setContextfromfile(false);
    $qformat->setStoponerror(true);
    $qformat->set_display_progress(false);
    ob_start();
    try {
        $imported = $qformat->importpreprocess()
            && $qformat->importprocess()
            && $qformat->importpostprocess();
    } finally {
        ob_end_clean();
    }
    if (!$imported || count($qformat->questionids) !== 6) {
        throw new \RuntimeException('Moodle XML import did not create the six demo questions.');
    }

    echo "Imported " . count($qformat->questionids) . " demo questions into question bank cmid={$questionbankcm->id}.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'Bulk tags demo provisioning failed: ' . $e->getMessage() . "\n");
}
